75	        {certifications.length > 0 && (
76	          <Badge variant="outline" className="text-[11px] h-5">{certifications.length} certs</Badge>
77	        )}
78	      </CardHeader>
79	      <CardContent className="px-4 pb-4 pt-0 space-y-4">
80	        {classified.length > 0 ? (
81	          <>
82	            <div className="space-y-3">
83	              {classified.slice(0, showAll ? undefined : 3).map((edu, i) => (
84	                <div key={i} className={`flex items-start gap-3 ${!edu.isRelevant ? "opacity-40" : ""}`}>
85	                  <div className={`mt-1.5 h-1.5 w-1.5 rounded-full shrink-0 ${edu.isMatched ? "bg-primary" : "bg-muted-foreground/40"}`} />
86	                  <div className="flex-1 min-w-0">
87	                    <div className="flex items-center gap-1.5 flex-wrap">
88	                      <span className="text-sm font-medium text-foreground">{edu.degree || "Degree"}</span>
89	                      <Badge variant="outline" className="text-[10px] h-4">{LEVEL_LABEL[edu.level]}</Badge>
90	                      {edu.isMatched && <Badge variant="secondary" className="text-[10px] h-4">JD Match</Badge>}
91	                    </div>
